function imgUrl(id,w=600){return `https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&q=82`}

function updateFeaturedGalleryPainting() {
    let topPainting = shop.reduce((max, item) => item[5] > max[5] ? item : max, shop[0]);
    let topIndex = shop.indexOf(topPainting);
    document.getElementById('topLikedCardContent').innerHTML = `
        <img src="${imgUrl(topPainting[4], 1100)}" alt="${topPainting[0]}">
        <div class="feature-info">
            <span class="tag">❤️ أعلى اللوحات إعجاباً (${topPainting[5]} إعجاب)</span>
            <h3>${topPainting[0]}</h3>
            <p>فنان العمل: ${topPainting[1]} · تصنيف (${topPainting[2]}). هذه اللوحة تتصدر معرضنا اليوم بناءً على تفضيلات وإعجابات زوار المنصة.</p>
            <div class="price">${topPainting[3]} ج.م</div>
            <button class="btn primary" style="width:max-content; margin-top:10px;" onclick="showShop(${topIndex})">عرض تفاصيل اللوحة</button>
        </div>
    `;
}

function shopCard(x,i){
    return `<article class="art-card" onclick="showShop(${i})">
        <img loading="lazy" src="${imgUrl(x[4])}" alt="${x[0]}">
        <div class="info">
            <h3>${x[0]}</h3>
            <p>الفنان: ${x[1]} · ${x[2]}</p>
            <div class="card-bottom">
                <b>${x[3]} ج.م</b>
                <div class="card-actions">
                    <button class="like-btn" id="like-btn-${i}" onclick="event.stopPropagation(); toggleLike(${i})">
                        ❤️ <span id="like-count-${i}">${x[5]}</span>
                    </button>
                    <button class="small-btn" onclick="event.stopPropagation();showShop(${i})">التفاصيل</button>
                </div>
            </div>
        </div>
    </article>`;
}

function toggleLike(i) {
    shop[i][5] += 1;
    document.getElementById(`like-count-${i}`).textContent = shop[i][5];
    let btn = document.getElementById(`like-btn-${i}`);
    btn.classList.add('liked');
    setTimeout(() => btn.classList.remove('liked'), 300);
    toast(`تم تسجيل إعجابك بـ "${shop[i][0]}"`);
    updateFeaturedGalleryPainting();
}

function renderStore() {
    let previewHTML = shop.slice(0,5).map((x,i)=>shopCard(x,i)).join('') + 
        `<div class="carousel-end"><div class="arrow">←</div><strong>وصلت لنهاية المجموعة</strong><span>اكتشف باقي اللوحات في المتجر الكامل</span><button class="btn primary" onclick="openPage('storePage')">عرض كل اللوحات</button></div>`;
    document.getElementById('storePreview').innerHTML = previewHTML;
    document.getElementById('allStoreGrid').innerHTML = shop.map((x,i)=>shopCard(x,i)).join('');
}
renderStore();
updateFeaturedGalleryPainting();

function courseCard(c,i){
    let min=Math.min(...Object.values(c.prices).map(v=>Number(v.replace(',',''))));
    return `<article class="art-card course-card" onclick="showCourse(${i})">
        <img loading="lazy" src="${c.imageData || imgUrl(c.image)}" alt="${c.title}">
        <div class="info">
            <span class="tag">3 مستويات</span>
            <h3 style="margin-top:9px">${c.title}</h3>
            <p>${c.duration} · مبتدئ ومتوسط ومحترف</p>
            <div class="card-bottom">
                <b>يبدأ من ${min.toLocaleString('en-US')} ج.م</b>
                <button class="small-btn">التفاصيل</button>
            </div>
        </div>
    </article>`;
}
document.getElementById('coursesGrid').innerHTML=courses.slice(0,4).map((c,i)=>courseCard(c,i)).join('');
document.getElementById('allCoursesGrid').innerHTML=courses.map((c,i)=>courseCard(c,i)).join('');

function showShop(i){
    let x=shop[i];
    openModal(`<img src="${imgUrl(x[4],1000)}" alt="${x[0]}"><div class="modal-content"><span class="tag">${x[2]}</span><h2>${x[0]}</h2><p>عمل فني من إبداع الفنان ${x[1]}، بتكوين لوني يلتقط تفاصيل ${x[2]} ويمنح المكان حضورًا مميزًا.</p><div class="price">${x[3]} ج.م</div><button class="btn primary" onclick="toast('تمت إضافة طلبك، سنتواصل معك قريبًا')">اطلب اللوحة</button></div>`);
}

function showCourse(i){
    let c=courses[i];
    let levels=Object.entries(c.prices).map(([level,price])=>`<div class="stat" style="background:#f6f2f8;color:#302b36;text-align:right"><b style="font-size:18px;color:var(--purple)">${level}</b><p style="margin:4px 0;color:#777">الرسوم: ${price} ج.م</p><button class="small-btn" onclick="toast('تم تسجيل طلبك في مستوى ${level}')">اختيار المستوى</button></div>`).join('');
    openModal(`<img src="${c.imageData || imgUrl(c.image,1000)}" alt="${c.title}"><div class="modal-content"><h2>${c.title}</h2><p>الدورة متاحة بثلاثة مستويات لتناسب خبرتك الحالية وتساعدك على التدرج في التعلم.</p><p>المدة المقترحة: ${c.duration}</p><h3>اختر المستوى المناسب</h3><div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px">${levels}</div></div>`);
}

function openModal(content){document.getElementById('modalBody').innerHTML=content;document.getElementById('modal').classList.add('open');document.body.style.overflow='hidden'}
function closeModal(){document.getElementById('modal').classList.remove('open');document.body.style.overflow=''}

function openPage(id){document.body.classList.add('page-open');document.querySelectorAll('.page-view').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');window.scrollTo({top:0,behavior:'smooth'});}
function closePage(){document.body.classList.remove('page-open');document.querySelectorAll('.page-view').forEach(x=>x.classList.remove('active'));document.getElementById('store').scrollIntoView({behavior:'smooth'});}

function showListingForm(){
    openModal(`<div class="modal-content"><h2>اعرض لوحتك للبيع</h2><p>أدخل بيانات لوحتك وسيتواصل معك فريق Art Haven لمراجعة الطلب.</p><form class="listing-form" onsubmit="event.preventDefault();toast('تم استلام بيانات لوحتك بنجاح');closeModal()"><input required placeholder="اسم اللوحة"><input required placeholder="اسم الفنان"><input required type="number" min="1" placeholder="السعر بالجنيه المصري"><input required type="tel" placeholder="رقم التواصل"><textarea rows="3" placeholder="وصف مختصر للوحة"></textarea><button class="btn primary" type="submit">إرسال اللوحة للمراجعة</button></form></div>`);
}

function toast(t){let e=document.getElementById('toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),2600)}

function artistModal(i){
    let x=famous[i];
    openModal(`<div class="modal-content" style="text-align:right;">
        <img src="${x.img}" alt="${x.title}" style="max-height:400px; object-fit:contain; margin-bottom:15px; border-radius:12px; background:#eee;">
        <span class="tag">العمل: ${x.title} (${x.year})</span>
        <h2 style="margin:10px 0 5px;">الفنان: ${x.artist}</h2>
        <h3 style="color:var(--purple); font-size:16px; margin-bottom:15px;">الاسم الأصلي للعمل: ${x.orig}</h3>
        <p style="line-height:2; color:#555;"><b>السيرة الذاتية والمعلومات:</b> ${x.bio}</p>
        <div style="margin-top:20px;">
            <a class="btn secondary" target="_blank" rel="noopener noreferrer" href="https://en.wikipedia.org/w/index.php?search=${encodeURIComponent(x.orig + " painting")}">اقرأ عن اللوحة في ويكيبيديا</a>
        </div>
    </div>`);
}

function renderFamous(){
    const masterCardHTML = (x,i)=>`<article class="art-card" onclick="artistModal(${i})">
        <img loading="lazy" alt="${x.title}" src="${x.img}">
        <div class="info">
            <h3>${x.title}</h3>
            <p>${x.artist}</p>
            <div class="card-bottom">
                <span>${x.year}</span>
                <div class="card-actions">
                    <a class="small-btn" target="_blank" rel="noopener noreferrer" onclick="event.stopPropagation()" href="https://en.wikipedia.org/w/index.php?search=${encodeURIComponent(x.orig + " painting")}">ويكيبيديا</a>
                </div>
            </div>
        </div>
    </article>`;

    document.getElementById('masterpiecesPreview').innerHTML = famous.slice(0,6).map((x,i)=>masterCardHTML(x,i)).join('') + 
        `<div class="carousel-end"><div class="arrow">←</div><strong>عرض الكل (51)</strong><span>تصفح جميع الروائع الفنية الخالدة</span><button class="btn primary" onclick="openPage('galleryPage')">فتح المعرض</button></div>`;
    
    document.getElementById('allMasterpiecesGrid').innerHTML = famous.map((x,i)=>masterCardHTML(x,i,false)).join('');
}
renderFamous();

document.getElementById('navToggle').addEventListener('click',()=>document.getElementById('navLinks').classList.toggle('open'));
document.querySelectorAll('.links a').forEach(a=>a.addEventListener('click',()=>document.getElementById('navLinks').classList.remove('open')));

const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});
document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));



/* ===== Art Haven: theme, fullscreen artwork, particles and motion ===== */
(() => {
  const ready = (fn) => {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", fn, { once: true });
    } else fn();
  };

  ready(() => {
    const body = document.body;
    const nav = document.querySelector(".nav");

    // Day / night theme with saved visitor preference
    const themeButton = document.createElement("button");
    themeButton.id = "ahThemeToggle";
    themeButton.type = "button";
    themeButton.setAttribute("aria-label", "تبديل الوضع الليلي والنهاري");
    themeButton.innerHTML = "🌙 الوضع الليلي";
    if (nav) {
      const navToggle = document.getElementById("navToggle");
      nav.insertBefore(themeButton, navToggle || null);
    } else {
      themeButton.style.position = "fixed";
      themeButton.style.top = "15px";
      themeButton.style.left = "15px";
      themeButton.style.zIndex = "100";
      body.appendChild(themeButton);
    }

    let savedTheme = "light";
    try { savedTheme = localStorage.getItem("artHavenTheme") || "light"; } catch (_) {}
    const applyTheme = (theme) => {
      body.classList.toggle("ah-dark", theme === "dark");
      themeButton.innerHTML = theme === "dark" ? "☀️ الوضع النهاري" : "🌙 الوضع الليلي";
      themeButton.setAttribute("aria-pressed", String(theme === "dark"));
      try { localStorage.setItem("artHavenTheme", theme); } catch (_) {}
    };
    applyTheme(savedTheme);
    themeButton.addEventListener("click", () => {
      applyTheme(body.classList.contains("ah-dark") ? "light" : "dark");
    });

    // Full-screen image viewer for artwork and course images
    const lightbox = document.createElement("div");
    lightbox.className = "ah-lightbox";
    lightbox.innerHTML = `
      <button class="ah-lightbox-close" type="button" aria-label="إغلاق">×</button>
      <img alt="">
      <span class="ah-lightbox-hint">اضغط خارج الصورة أو Esc للإغلاق</span>`;
    body.appendChild(lightbox);
    const lightboxImage = lightbox.querySelector("img");
    const closeLightbox = () => {
      lightbox.classList.remove("open");
      body.style.overflow = "";
      setTimeout(() => { if (!lightbox.classList.contains("open")) lightboxImage.removeAttribute("src"); }, 320);
    };
    document.addEventListener("click", (event) => {
      const image = event.target.closest(
        ".art-card img, .course-card img, .feature-card img, #topLikedCardContent img"
      );
      if (image && !event.target.closest(".ah-lightbox")) {
        event.preventDefault();
        event.stopPropagation();
        lightboxImage.src = image.currentSrc || image.src;
        lightboxImage.alt = image.alt || "لوحة فنية";
        lightbox.classList.add("open");
        body.style.overflow = "hidden";
        return;
      }
      if (event.target === lightbox || event.target.closest(".ah-lightbox-close")) closeLightbox();
    }, true);
    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && lightbox.classList.contains("open")) closeLightbox();
    });

    // Gentle floating art particles in the hero area
    const hero = document.querySelector(".hero");
    if (hero && !window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      const canvas = document.createElement("canvas");
      canvas.id = "ahParticles";
      hero.prepend(canvas);
      const ctx = canvas.getContext("2d");
      let particles = [];
      let width = 0, height = 0, raf = 0;
      const resize = () => {
        const rect = hero.getBoundingClientRect();
        const dpr = Math.min(window.devicePixelRatio || 1, 2);
        width = rect.width; height = rect.height;
        canvas.width = Math.round(width * dpr);
        canvas.height = Math.round(height * dpr);
        canvas.style.width = width + "px";
        canvas.style.height = height + "px";
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        const count = Math.min(110, Math.max(55, Math.floor(width / 11)));
        particles = Array.from({ length: count }, () => ({
          x: Math.random() * width,
          y: Math.random() * height,
          r: Math.random() * 2 + .7,
          vx: (Math.random() - .5) * .32,
          vy: -Math.random() * .35 - .08,
          a: Math.random() * .48 + .18
        }));
      };
      const draw = () => {
        ctx.clearRect(0, 0, width, height);
        for (const p of particles) {
          p.x += p.vx; p.y += p.vy;
          if (p.y < -8) { p.y = height + 8; p.x = Math.random() * width; }
          if (p.x < -8) p.x = width + 8;
          if (p.x > width + 8) p.x = -8;
          ctx.beginPath();
          ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(201,156,84,${p.a})`;
          ctx.fill();
        }
        raf = requestAnimationFrame(draw);
      };
      resize();
      draw();
      window.addEventListener("resize", resize, { passive: true });
      document.addEventListener("visibilitychange", () => {
        if (document.hidden) cancelAnimationFrame(raf);
        else if (!raf || document.visibilityState === "visible") draw();
      });
    }

    // Scroll progress and back-to-top control
    const progress = document.createElement("div");
    progress.id = "ahProgress";
    body.appendChild(progress);
    const backTop = document.createElement("button");
    backTop.id = "ahBackTop";
    backTop.type = "button";
    backTop.textContent = "↑";
    backTop.title = "العودة للأعلى";
    backTop.setAttribute("aria-label", "العودة إلى أعلى الصفحة");
    body.appendChild(backTop);
    const updateScroll = () => {
      const max = document.documentElement.scrollHeight - window.innerHeight;
      progress.style.width = (max > 0 ? Math.min(100, window.scrollY / max * 100) : 0) + "%";
      backTop.classList.toggle("show", window.scrollY > 420);
    };
    window.addEventListener("scroll", updateScroll, { passive: true });
    updateScroll();
    backTop.addEventListener("click", () => window.scrollTo({ top: 0, behavior: "smooth" }));

    // Button press ripple
    document.addEventListener("click", (event) => {
      const button = event.target.closest("button, .btn");
      if (!button || button.id === "ahBackTop") return;
      const rect = button.getBoundingClientRect();
      const ripple = document.createElement("span");
      const size = Math.max(rect.width, rect.height);
      ripple.className = "ah-ripple";
      ripple.style.width = ripple.style.height = size + "px";
      ripple.style.left = (event.clientX - rect.left - size / 2) + "px";
      ripple.style.top = (event.clientY - rect.top - size / 2) + "px";
      const oldPosition = getComputedStyle(button).position;
      if (oldPosition === "static") button.style.position = "relative";
      button.style.overflow = "hidden";
      button.appendChild(ripple);
      setTimeout(() => ripple.remove(), 650);
    });

    // Smooth page-view transitions while preserving the site's own page logic
    if (typeof window.openPage === "function" && !window.openPage.__ahWrapped) {
      const originalOpenPage = window.openPage;
      const wrappedOpenPage = function(...args) {
        body.classList.remove("ah-page-transition");
        void body.offsetWidth;
        body.classList.add("ah-page-transition");
        const result = originalOpenPage.apply(this, args);
        setTimeout(() => body.classList.remove("ah-page-transition"), 480);
        return result;
      };
      wrappedOpenPage.__ahWrapped = true;
      window.openPage = wrappedOpenPage;
    }
    if (typeof window.closePage === "function" && !window.closePage.__ahWrapped) {
      const originalClosePage = window.closePage;
      const wrappedClosePage = function(...args) {
        body.classList.add("ah-page-transition");
        const result = originalClosePage.apply(this, args);
        setTimeout(() => body.classList.remove("ah-page-transition"), 480);
        return result;
      };
      wrappedClosePage.__ahWrapped = true;
      window.closePage = wrappedClosePage;
    }

    // Animate dynamically added cards without changing their content
    const cardObserver = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add("ah-card-seen");
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: .08 });
    const watchCards = () => {
      document.querySelectorAll(".art-card, .course-card, .feature-card").forEach(card => {
        if (!card.dataset.ahMotionSeen) {
          card.dataset.ahMotionSeen = "1";
          cardObserver.observe(card);
        }
      });
    };
    watchCards();
    new MutationObserver(watchCards).observe(document.body, { childList: true, subtree: true });
  });
})();


/* Art Haven Luxury Experiences */
(() => {
 const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch(e){return d}};
 const write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}};
 const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
 let ci=0, qs=[], qi=0, score=0, locked=false;
 function cinemaLayer(){
  if(document.getElementById("ahCinema"))return;
  const d=document.createElement("div");d.id="ahCinema";d.className="ah-cinema";
  d.innerHTML='<button class="ah-cinema-close" onclick="closeArtCinema()">×</button><button class="ah-cinema-arrow prev" onclick="stepArtCinema(-1)">‹</button><figure class="ah-cinema-figure"><img id="ahCinemaImage"><figcaption id="ahCinemaCaption"></figcaption></figure><button class="ah-cinema-arrow next" onclick="stepArtCinema(1)">›</button><div id="ahCinemaCounter" class="ah-cinema-counter"></div>';
  document.body.appendChild(d);
  let x=0;d.addEventListener("touchstart",e=>x=e.changedTouches[0].clientX,{passive:true});
  d.addEventListener("touchend",e=>{let dx=e.changedTouches[0].clientX-x;if(Math.abs(dx)>55)stepArtCinema(dx>0?-1:1)},{passive:true});
  d.addEventListener("click",e=>{if(e.target===d)closeArtCinema()});
 }
 function paint(){let a=famous[ci];document.getElementById("ahCinemaImage").src=a.img;document.getElementById("ahCinemaImage").alt=a.title;document.getElementById("ahCinemaCaption").innerHTML=`<strong>${esc(a.title)}</strong><span>${esc(a.artist)} · ${esc(a.year)}</span>`;document.getElementById("ahCinemaCounter").textContent=`${ci+1} / ${famous.length}`}
 window.startArtCinema=(i=0)=>{cinemaLayer();ci=Math.max(0,Math.min(+i||0,famous.length-1));paint();document.getElementById("ahCinema").classList.add("open");document.body.style.overflow="hidden"};
 window.stepArtCinema=n=>{ci=(ci+n+famous.length)%famous.length;paint()};
 window.closeArtCinema=()=>{document.getElementById("ahCinema")?.classList.remove("open");document.body.style.overflow=""};

 // Expand existing artwork details into a story-led view, preserving original artist facts and Wikipedia link.
 window.artistModal=function(i){
  const a=famous[i];openModal(`<div class="modal-content ah-story-content"><img class="ah-story-image" src="${esc(a.img)}" alt="${esc(a.title)}"><span class="tag">العمل الفني · ${esc(a.year)}</span><h2>${esc(a.title)}</h2><h3>الفنان: ${esc(a.artist)}</h3><p class="ah-story-original">${esc(a.orig)}</p><div class="ah-story-block"><b>السيرة الذاتية والمعلومات</b><p>${esc(a.bio||"عمل فني يحتفظ بمكانته في تاريخ الفن ويكشف عن رؤية الفنان وأسلوبه.")}</p></div><div class="ah-story-block"><b>تأمل بصري</b><p>تأمل توزيع العناصر والألوان وطريقة توجيه النظر داخل التكوين. حاول ملاحظة التفاصيل التي تمنح العمل شخصيته، ثم أعد مشاهدة اللوحة لاكتشاف تفاصيل جديدة.</p></div><div class="ah-story-actions"><button class="btn primary" onclick="closeModal();startArtCinema(${i})">مشاهدة سينمائية</button><a class="btn secondary" target="_blank" rel="noopener noreferrer" href="https://en.wikipedia.org/w/index.php?search=${encodeURIComponent(a.orig+" painting")}">معلومات إضافية</a></div></div>`);
 };

 function renderProgress(){
  const root=document.getElementById("ahProgressWidget");if(!root)return;
  const done=read("ahCompletedCourses",[]),n=courses.filter((c,i)=>done.includes(i)).length,p=Math.round(n/courses.length*100);
  root.innerHTML=`<div class="ah-progress-top"><strong>${n} من ${courses.length} دورات</strong><b>${p}%</b></div><div class="ah-progress-track"><span style="width:${p}%"></span></div><button class="ah-text-button" onclick="openCourseProgress()">إدارة تقدمي</button>`;
 }
 window.openCourseProgress=()=>{
  const done=read("ahCompletedCourses",[]);
  const rows=courses.map((c,i)=>`<label class="ah-course-check"><input type="checkbox" ${done.includes(i)?"checked":""} onchange="toggleCourseProgress(${i},this.checked)"><span>${esc(c.title)}</span></label>`).join("");
  openModal(`<div class="modal-content ah-progress-modal"><span class="kicker">رحلتك التعليمية</span><h2>متابعة تقدّم الدورات</h2><p>حدد الدورات التي أنهيتها. سيتم حفظ اختيارك على هذا الجهاز.</p><div class="ah-course-check-list">${rows}</div><p id="ahProgressSummary"></p><button class="btn primary" onclick="closeModal()">تم</button></div>`);
  updateSummary();
 };
 window.toggleCourseProgress=(i,v)=>{let d=read("ahCompletedCourses",[]);d=v?[...new Set([...d,i])]:d.filter(x=>x!==i);write("ahCompletedCourses",d);renderProgress();updateSummary()};
 function updateSummary(){let e=document.getElementById("ahProgressSummary");if(e)e.textContent=`أنهيت ${read("ahCompletedCourses",[]).length} من ${courses.length} دورات`}

 function makeQuestions(){
  let pool=[...famous];for(let i=pool.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}
  return pool.slice(0,8).map((a,n)=>{let artist=n%2===0,correct=artist?a.artist:a.title,opts=[correct,...pool.filter(x=>x!==a).slice(n,n+3).map(x=>artist?x.artist:x.title)];opts=[...new Set(opts)].slice(0,4);while(opts.length<4)opts.push(artist?famous[opts.length].artist:famous[opts.length].title);for(let i=opts.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[opts[i],opts[j]]=[opts[j],opts[i]]}return{a,artist,correct,opts}});
 }
 window.startArtQuiz=()=>{qs=makeQuestions();qi=0;score=0;locked=false;showQuestion()};
 function showQuestion(){
  let q=qs[qi],buttons=q.opts.map((o,i)=>`<button class="ah-quiz-option" onclick="answerArtQuiz(${i})">${esc(o)}</button>`).join("");
  openModal(`<div class="modal-content ah-quiz"><span class="kicker">التحدّي الفني</span><div class="ah-quiz-progress"><span style="width:${qi/qs.length*100}%"></span></div><p class="ah-quiz-meta">السؤال ${qi+1} من ${qs.length}</p><img class="ah-quiz-image" src="${esc(q.a.img)}" alt="${esc(q.a.title)}"><h2>${q.artist?"من صاحب هذه اللوحة؟":"ما اسم هذه اللوحة؟"}</h2><div class="ah-quiz-options">${buttons}</div><p id="ahQuizFeedback" aria-live="polite"></p><button id="ahQuizNext" class="btn primary" style="display:none" onclick="nextArtQuiz()">${qi===qs.length-1?"عرض النتيجة":"التالي"}</button></div>`);
  locked=false;
 }
 window.answerArtQuiz=i=>{
  if(locked)return;locked=true;let q=qs[qi],chosen=q.opts[i];if(chosen===q.correct)score++;
  document.querySelectorAll(".ah-quiz-option").forEach((b,n)=>{b.disabled=true;if(q.opts[n]===q.correct)b.classList.add("correct");else if(n===i)b.classList.add("wrong")});
  document.getElementById("ahQuizFeedback").textContent=chosen===q.correct?"إجابة صحيحة! أحسنت.":`الإجابة الصحيحة: ${q.correct}`;
  document.getElementById("ahQuizNext").style.display="inline-flex";
 };
 window.nextArtQuiz=()=>{if(qi<qs.length-1){qi++;showQuestion()}else openModal(`<div class="modal-content ah-quiz-result"><span class="kicker">انتهى التحدّي</span><h2>نتيجتك الفنية</h2><div class="ah-quiz-score">${score}<small> / ${qs.length}</small></div><p>${score>=7?"رائع! لديك ذاكرة فنية قوية.":score>=4?"أداء جميل! واصل اكتشاف الأعمال.":"بداية موفقة؛ تجوّل في المعرض وحاول مرة أخرى."}</p><button class="btn primary" onclick="startArtQuiz()">إعادة الاختبار</button></div>`)};
 document.addEventListener("keydown",e=>{if(document.getElementById("ahCinema")?.classList.contains("open")){if(e.key==="Escape")closeArtCinema();if(e.key==="ArrowRight")stepArtCinema(-1);if(e.key==="ArrowLeft")stepArtCinema(1)}});
 if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",renderProgress,{once:true});else renderProgress();
})();
